insert into public.colors(key,label,hex,sort_order) values('black','שחור','#222222',1),('white','לבן','#F7F7F7',2),('gray','אפור','#8A8A8A',3),('brown','חום','#8B5E3C',4),('beige','בז׳ / טבעי','#D8C8A8',5),('red','אדום','#D84A4A',6),('orange','כתום','#E88732',7),('yellow','צהוב','#E3C33B',8),('green','ירוק','#4F9B62',9),('turquoise','טורקיז','#00CED1',10),('light_blue','תכלת','#00BFFF',11),('blue','כחול','#0000FF',12),('purple','סגול','#9C46C7',13),('pink','ורוד','#E889A7',14),('metallic','מטאלי','#A7A7A7',15) on conflict(key) do update set label=excluded.label,hex=excluded.hex,sort_order=excluded.sort_order,active=true;
with r(name,ord) as(values('צפון',1),('חיפה, הקריות וחוף הכרמל',2),('השרון',3),('גוש דן',4),('השפלה',5),('ירושלים והסביבה',6),('יהודה ושומרון',7),('הדרום',8)) insert into public.regions(name,sort_order) select name,ord from r on conflict(name) do update set sort_order=excluded.sort_order;
do $$declare rid uuid;begin select id into rid from public.regions where name='צפון';insert into public.subregions(region_id,name,sort_order) values(rid,'רמת הגולן',1),(rid,'קריית שמונה, ראש פינה ועמק החולה',2),(rid,'נהריה, עכו והגליל המערבי',3),(rid,'כרמיאל ומשגב',4),(rid,'טבריה והכנרת',5),(rid,'נצרת, שפרעם והגליל התחתון',6),(rid,'עפולה והעמקים',7),(rid,'בית שאן והעמק',8) on conflict do nothing;select id into rid from public.regions where name='חיפה, הקריות וחוף הכרמל';insert into public.subregions(region_id,name,sort_order) values(rid,'חיפה',1),(rid,'הקריות',2),(rid,'זכרון יעקב וחוף הכרמל',3),(rid,'קיסריה',4),(rid,'חדרה',5),(rid,'טבעון ויקנעם',6),(rid,'רמות מנשה',7) on conflict do nothing;select id into rid from public.regions where name='השרון';insert into public.subregions(region_id,name,sort_order) values(rid,'נתניה',1),(rid,'צפון השרון',2),(rid,'רעננה וכפר סבא',3),(rid,'הוד השרון',4),(rid,'רמת השרון והרצליה',5),(rid,'ראש העין',6) on conflict do nothing;select id into rid from public.regions where name='גוש דן';insert into public.subregions(region_id,name,sort_order) values(rid,'בני ברק וגבעת שמואל',1),(rid,'פתח תקווה',2),(rid,'רמת גן וגבעתיים',3),(rid,'תל אביב–יפו',4),(rid,'בקעת אונו',5),(rid,'חולון ובת ים',6),(rid,'ראשון לציון',7) on conflict do nothing;select id into rid from public.regions where name='השפלה';insert into public.subregions(region_id,name,sort_order) values(rid,'נס ציונה ורחובות',1),(rid,'גדרה ויבנה',2),(rid,'אשדוד ואשקלון',3),(rid,'קריית גת',4),(rid,'רמלה–לוד',5),(rid,'שוהם',6) on conflict do nothing;select id into rid from public.regions where name='ירושלים והסביבה';insert into public.subregions(region_id,name,sort_order) values(rid,'הרי יהודה ומבשרת',1),(rid,'ירושלים',2),(rid,'מעלה אדומים',3),(rid,'בית שמש',4),(rid,'מודיעין',5),(rid,'עמק איילון',6) on conflict do nothing;select id into rid from public.regions where name='יהודה ושומרון';insert into public.subregions(region_id,name,sort_order) values(rid,'יישובי השומרון',1),(rid,'אריאל ויישובי יהודה',2),(rid,'בקעת הירדן וצפון ים המלח',3),(rid,'גוש עציון',4),(rid,'דרום הר חברון',5) on conflict do nothing;select id into rid from public.regions where name='הדרום';insert into public.subregions(region_id,name,sort_order) values(rid,'באר שבע',1),(rid,'הנגב המערבי',2),(rid,'דרום ים המלח',3),(rid,'הר הנגב',4),(rid,'אילת והערבה',5) on conflict do nothing;end$$;
insert into public.materials(name,vegan,material_origin) values('כותנה',true,'natural'),('משי',false,'natural'),('צמר',false,'natural'),('שיער בעלי חיים',false,'natural'),('פשתן',true,'natural'),('קנבוס',true,'natural'),('טנסל',true,'artificial'),('ויסקוזה',true,'artificial'),('במבוק',true,'artificial'),('קפוק',true,'natural'),('פוליאסטר',true,'synthetic') on conflict do nothing;
do $$declare cotton uuid;silk uuid;wool uuid;animal uuid;begin select id into cotton from public.materials where normalized_name='כותנה';select id into silk from public.materials where normalized_name='משי';select id into wool from public.materials where normalized_name='צמר';select id into animal from public.materials where normalized_name='שיער בעלי חיים';insert into public.materials(name,parent_material_id,vegan,material_origin) values('כותנה מצרית',cotton,true,'natural'),('כותנה אורגנית',cotton,true,'natural'),('כותנת פימה',cotton,true,'natural'),('משי טוסה',silk,false,'natural'),('משי מאלברי',silk,false,'natural'),('מרינו',wool,false,'natural'),('קשמיר',animal,false,'natural'),('אלפקה',animal,false,'natural') on conflict do nothing;end$$;
insert into public.field_help(field_key,content,show_in_form,show_on_listing,show_in_filter) values('manufacturer','שם החברה או האורגת שייצרה את המנשא.',true,false,false),('design','שם העיצוב או הדוגמה של המנשא.',true,false,false),('model','שם המודל המדויק, אם קיים.',true,false,false),('size','בחרי מידה רשמית; חריגות אפשר לציין בהערת המידה.',true,false,false),('gsm','בחרי את קטגוריית ה-GSM המתאימה; אם לא ידוע בחרי "לא ידוע".',true,true,true),('shipping','דמי משלוח על חשבון הקונה אלא אם צוין אחרת.',true,true,false) on conflict(field_key) do update set content=excluded.content;
